UPDATE conservationandmaintenance
SET maintlog = maintlog || ' [ALERT: Urgent conservation required - ' || CURRENT_TIMESTAMP::text || ']'
WHERE treatpriority = 'Urgent';

UPDATE conservationandmaintenance
SET maintlog = maintlog || ' [ALERT: Urgent conservation required - ' || NOW()::text || ']'
WHERE treatpriority = 'Urgent';

UPDATE conservationandmaintenance
SET maintlog = maintlog || ' [ALERT: Urgent conservation - ' || NOW()::text || ']'
WHERE treatpriority = 'Urgent';

UPDATE conservationandmaintenance
SET maintlog = maintlog || ' [ALERT: Urgent conservation - ' || CURRENT_TIMESTAMP || ']'
WHERE treatpriority = 'Urgent';

UPDATE conservationandmaintenance
SET maintlog = maintlog || ' [ALERT: Urgent conservation - ' || CURRENT_TIMESTAMP::text || ']'
WHERE conservetreatstatus = 'In Progress' AND treatpriority IN ('Urgent', 'High');

UPDATE conservationandmaintenance
SET maintlog = CONCAT(maintlog, ' [ALERT: Urgent conservation - ', CURRENT_TIMESTAMP, ']')
WHERE treatpriority = 'Urgent';
